@namespace sv_6308fbbecbdc46bfafce941e2f8f202c.Components.Pages.Settings
@using sv_6308fbbecbdc46bfafce941e2f8f202c.Models

<div class="appearance-section">
    <h4 class="mb-4">Appearance Settings</h4>

    @if (ShowSuccess)
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            Appearance saved!
            <button type="button" class="btn-close" @onclick="() => ShowSuccess = false"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-7">
            <!-- Theme -->
            <div class="card mb-3">
                <div class="card-body">
                    <h6 class="card-title">Theme</h6>
                    <div class="d-flex gap-3">
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                                       value="@theme" checked="@(Theme == theme)"
                                       @onchange="() => Theme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>
                </div>
            </div>

            <!-- Font Size -->
            <div class="card mb-3">
                <div class="card-body">
                    <h6 class="card-title">Font Size</h6>
                    <div class="d-flex gap-3">
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                                       value="@size" checked="@(FontSize == size)"
                                       @onchange="() => FontSize = size" />
                                <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                            </div>
                        }
                    </div>
                </div>
            </div>

            <!-- Language -->
            <div class="card mb-3">
                <div class="card-body">
                    <h6 class="card-title">Language</h6>
                    <select class="form-select" @bind="Language">
                        <option value="English">English</option>
                        <option value="Spanish">Spanish</option>
                        <option value="French">French</option>
                        <option value="German">German</option>
                        <option value="Japanese">Japanese</option>
                    </select>
                </div>
            </div>

            <!-- Compact Mode -->
            <div class="card mb-3">
                <div class="card-body">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="CompactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
        </div>

        <!-- Live Preview -->
        <div class="col-md-5">
            <div class="card">
                <div class="card-header">
                    <h6 class="mb-0">Preview</h6>
                </div>
                <div class="card-body @GetPreviewClasses()" style="@GetPreviewStyles()">
                    <h6 style="@GetFontStyle()">Sample Heading</h6>
                    <p style="@GetFontStyle()" class="@(CompactMode ? "mb-1" : "mb-3")">
                        This is how your content will look with the selected appearance settings.
                    </p>
                    <div class="d-flex gap-2 @(CompactMode ? "mb-1" : "mb-2")">
                        <span class="badge bg-primary">Tag 1</span>
                        <span class="badge bg-secondary">Tag 2</span>
                    </div>
                    <button class="btn btn-sm btn-primary" style="@GetFontStyle()">Sample Button</button>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string Theme { get; set; } = "Light";
    private string FontSize { get; set; } = "Medium";
    private string Language { get; set; } = "English";
    private bool CompactMode { get; set; }
    private bool ShowSuccess { get; set; }
    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            Theme = Settings.Theme;
            FontSize = Settings.FontSize;
            Language = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
        await OnSave.InvokeAsync(updated);
        ShowSuccess = true;
    }

    private string GetPreviewClasses()
    {
        return Theme == "Dark" ? "bg-dark text-light" : "bg-light text-dark";
    }

    private string GetPreviewStyles()
    {
        var padding = CompactMode ? "padding: 0.5rem;" : "padding: 1rem;";
        return $"{padding} min-height: 200px; transition: all 0.3s ease;";
    }

    private string GetFontStyle() => FontSize switch
    {
        "Small" => "font-size: 0.8rem;",
        "Large" => "font-size: 1.2rem;",
        _ => "font-size: 1rem;"
    };
}

